def f(n):
    if n == 0:
        return 0
    return n + f(n - 1)

print(f(4))

def g(L):
    if len(L) == 0:
        return 0
    if L[0] > 0:
        return 1 + g(L[1:])
    return g(L[1:])

print(g([3, -1, 0, 7, -5, 2]))

def h(n):
    if n <= 1:
        return 1
    return h(n - 1) + h(n - 2)

print(h(5))

def t(n):
    if n == 0:
        return 0
    return 1 + t(n - 2)
